insert into public.crops (slug, name, other_names, scientific_name, category, life_cycle, difficulty, sun, water, frost_sensitive, space_types, growth_days_min, growth_days_max, growth_note, summary, watering_summary, image_alt, data_status, source_note, propagation, primary_method, flowering_note, harvest_note, first_yield_note, estimate_dataset, estimate_harvest_meaning, estimate_note, estimate_links, estimate_review_notes) values ('tomato', 'البندورة', array['الطماطم','الطماطة','البندورة البلدية']::text[], 'Solanum lycopersicum', 'fruiting_vegetable', 'annual', 'medium', 'full_sun', 'moderate', true, array['home_garden','rooftop','balcony','containers','small_plot','farm']::text[], 60, 90, 'تقريبًا من الشتل حتى بداية القطف، ويختلف حسب الصنف ودرجات الحرارة.', 'من أشهر محاصيل الحدائق المنزلية. تحب الدفء والشمس، وتتأثر بالصقيع وبعدم انتظام الري.', 'ري منتظم وعميق عند جفاف سطح التربة، مع تجنب تبليل الأوراق.', 'ثمار بندورة حمراء ناضجة على النبات', 'preliminary', 'معلومات عامة أولية مجمّعة من الممارسات الزراعية الشائعة في بلاد الشام، ولم تُراجع بعد من مهندس زراعي. تختلف النتائج حسب الصنف والتربة والمناخ المحلي، لذا استشر الإرشاد الزراعي في منطقتك.', array['transplanting']::text[], null, null, null, null, null, null, null, '{}'::text[], '{}'::text[]) on conflict (slug) do update set other_names = (public.crops.other_names || array(select x from unnest(excluded.other_names) as u(x) where not (x = any(public.crops.other_names))))[1:12], propagation = case when cardinality(public.crops.propagation) = 0 then excluded.propagation else public.crops.propagation end, data_status = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.data_status else public.crops.data_status end, summary = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.summary else public.crops.summary end, source_note = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.source_note else public.crops.source_note end, primary_method = coalesce(public.crops.primary_method, excluded.primary_method), flowering_note = coalesce(public.crops.flowering_note, excluded.flowering_note), harvest_note = coalesce(public.crops.harvest_note, excluded.harvest_note), first_yield_note = coalesce(public.crops.first_yield_note, excluded.first_yield_note), estimate_dataset = case when public.crops.updated_by is null then excluded.estimate_dataset else public.crops.estimate_dataset end, estimate_harvest_meaning = case when public.crops.updated_by is null then excluded.estimate_harvest_meaning else public.crops.estimate_harvest_meaning end, estimate_note = case when public.crops.updated_by is null then excluded.estimate_note else public.crops.estimate_note end, estimate_links = case when public.crops.updated_by is null then excluded.estimate_links else public.crops.estimate_links end, estimate_review_notes = case when public.crops.updated_by is null then excluded.estimate_review_notes else public.crops.estimate_review_notes end;
insert into public.crop_planting_windows (crop_id, zone, country_code, start_month, end_month, method, note, source_id, source_detail, confidence, optional, sort_order) select (select id from public.crops where slug = 'tomato'), v.zone, v.country_code, v.start_month, v.end_month, v.method, v.note, v.source_id, v.source_detail, v.confidence, v.optional, v.sort_order from (values ('coastal', null, 2, 4, 'transplanting', 'العروة الربيعية', null, null, 'documented', false, 0), ('coastal', null, 8, 9, 'transplanting', 'العروة الخريفية', null, null, 'documented', false, 1), ('highland', null, 4, 5, 'transplanting', 'بعد زوال خطر الصقيع', null, null, 'documented', false, 2), ('inland_plain', null, 3, 4, 'transplanting', null, null, null, 'documented', false, 3), ('jordan_valley', null, 9, 11, 'transplanting', 'الموسم الخريفي الشتوي', null, null, 'documented', false, 4), ('arid', null, 9, 10, 'transplanting', 'مع حماية من الحر والرياح', null, null, 'documented', false, 5)) as v(zone, country_code, start_month, end_month, method, note, source_id, source_detail, confidence, optional, sort_order) where not exists (select 1 from public.crop_planting_windows x where x.crop_id = (select id from public.crops where slug = 'tomato') and x.confidence = 'documented') and (select updated_by from public.crops where slug = 'tomato') is null;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'tomato'), 'soil', 'soil_prep', 'تجهيز التربة للبندورة', 'اقلب التربة وأضف سمادًا عضويًا متحللًا جيدًا، وتأكد من تصريف المياه. في الأصص استخدم وعاءً لا يقل عن 20 لترًا.', -10, null, null, '{}'::int[], 0) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'tomato'), 'plant', 'planting', 'شتل أشتال البندورة', 'ازرع الأشتال في المساء أو في يوم غير حار، واروِ مباشرة بعد الشتل. اترك مسافة كافية بين النباتات للتهوية.', 0, null, null, '{}'::int[], 1) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'tomato'), 'water', 'irrigation', 'متابعة ري البندورة', 'افحص رطوبة التربة بإصبعك على عمق 3–5 سم واروِ عند جفافها فقط. تجاوز المهمة إذا هطلت أمطار كافية أو كانت التربة رطبة؛ فالحاجة الفعلية تتأثر بنوع التربة والطقس وعمر النبات.', 2, 3, 90, '{}'::int[], 2) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'tomato'), 'check-establish', 'care', 'تفقّد ثبات الأشتال', 'استبدل الأشتال الذابلة أو التالفة، وتأكد من عدم وجود حشرات تحت الأوراق.', 7, null, null, '{}'::int[], 3) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'tomato'), 'support', 'care', 'تركيب الدعامات وربط النباتات', 'ثبّت دعامة أو خيطًا لكل نبات قبل أن يثقل، وأزل الأفرع الجانبية السفلية إن كان الصنف غير محدود النمو.', 21, null, null, '{}'::int[], 4) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'tomato'), 'fert-flower', 'fertilizing', 'تسميد عند بداية التزهير', 'أضف سمادًا متوازنًا أو كمبوستًا حول النبات بعيدًا قليلًا عن الساق، ثم اروِ. التزم بتعليمات عبوة السماد.', 30, null, null, '{}'::int[], 5) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'tomato'), 'fert-fruit', 'fertilizing', 'تسميد خلال عقد الثمار', 'يساعد التسميد المعتدل والري المنتظم على تقليل تعفن الطرف الزهري.', 50, null, null, '{}'::int[], 6) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'tomato'), 'pests', 'pest_check', 'فحص الآفات على البندورة', 'افحص الأوراق من الجهتين بحثًا عن الذبابة البيضاء وأنفاق حافرة الأوراق (توتا) وبقع اللفحة، وأزل الأوراق المصابة.', 14, 7, 90, '{}'::int[], 7) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'tomato'), 'harvest', 'harvest', 'بداية موسم قطف البندورة المتوقع', 'اقطف الثمار عند تلوّنها، وتابع القطف كل بضعة أيام. الموعد تقريبي ويعتمد على الصنف والطقس.', 60, null, null, '{}'::int[], 8) on conflict (crop_id, key) do nothing;
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'tomato'), 'overview', 'نظرة عامة', 'البندورة نبات موسمي محب للدفء، لا يتحمل الصقيع، ويحتاج إلى 6–8 ساعات من الشمس المباشرة يوميًا. تُزرع غالبًا بالأشتال، ويوجد منها أصناف محدودة النمو (قصيرة) وأخرى غير محدودة تحتاج إلى دعامات.', 0 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'tomato') and x.section = 'overview');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'tomato'), 'planting', 'الزراعة', 'تُشتل البندورة بعد أن تدفأ التربة ويزول خطر الصقيع. في المناطق الساحلية تُزرع في الربيع والخريف، وفي المرتفعات في أواخر الربيع، وفي الأغوار في الخريف. ازرع الشتلة أعمق قليلًا من مستواها في الصينية لأنها تكوّن جذورًا على الساق.', 1 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'tomato') and x.section = 'planting');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'tomato'), 'care', 'العناية', 'اربط النباتات على دعامات، وأزل الأفرع الجانبية في الأصناف غير المحدودة، وغطِّ التربة بطبقة من القش أو الأوراق الجافة لحفظ الرطوبة. أزل الأوراق السفلية الملامسة للتربة لتقليل الأمراض.', 2 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'tomato') and x.section = 'care');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'tomato'), 'irrigation', 'الري', 'الأهم هو الانتظام: الري العميق المتباعد أفضل من الري السطحي اليومي. التذبذب الكبير بين الجفاف والغمر يسبب تشقق الثمار وتعفن طرفها. في الأصص تجف التربة أسرع وتحتاج إلى متابعة أكثر.', 3 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'tomato') and x.section = 'irrigation');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'tomato'), 'fertilization', 'التسميد', 'يكفي غالبًا سماد عضوي متحلل عند تجهيز التربة، ثم تسميد معتدل عند التزهير وعقد الثمار. الإفراط في الآزوت يعطي نموًا خضريًا كثيفًا على حساب الثمار.', 4 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'tomato') and x.section = 'fertilization');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'tomato'), 'harvest', 'الحصاد', 'تبدأ الثمار بالنضج تقريبًا بعد شهرين إلى ثلاثة أشهر من الشتل حسب الصنف والحرارة. اقطفها عند اكتمال اللون أو قبل ذلك بقليل لتكتمل في الظل.', 5 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'tomato') and x.section = 'harvest');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'tomato'), 'problems', 'المشكلات الشائعة', 'حافرة أوراق البندورة (توتا أبسلوتا)، والذبابة البيضاء، واللفحة المبكرة والمتأخرة، وتعفن الطرف الزهري المرتبط بعدم انتظام الري ونقص الكالسيوم المتاح، وتساقط الأزهار في الحر الشديد.', 6 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'tomato') and x.section = 'problems');
insert into public.crops (slug, name, other_names, scientific_name, category, life_cycle, difficulty, sun, water, frost_sensitive, space_types, growth_days_min, growth_days_max, growth_note, summary, watering_summary, image_alt, data_status, source_note, propagation, primary_method, flowering_note, harvest_note, first_yield_note, estimate_dataset, estimate_harvest_meaning, estimate_note, estimate_links, estimate_review_notes) values ('cucumber', 'الخيار', array['الخيار البلدي','خيار الأكل']::text[], 'Cucumis sativus', 'fruiting_vegetable', 'annual', 'easy', 'full_sun', 'high', true, array['home_garden','rooftop','balcony','containers','small_plot','farm']::text[], 50, 70, 'تقريبًا من البذر حتى أول قطفة.', 'محصول سريع النمو يحب الدفء والرطوبة المنتظمة، ويمكن تسلقه على شبكة لتوفير المساحة.', 'يحتاج إلى رطوبة منتظمة؛ الجفاف يسبب مرارة الثمار وتشوهها.', 'ثمار خيار خضراء طازجة', 'preliminary', 'معلومات عامة أولية مجمّعة من الممارسات الزراعية الشائعة في بلاد الشام، ولم تُراجع بعد من مهندس زراعي. تختلف النتائج حسب الصنف والتربة والمناخ المحلي، لذا استشر الإرشاد الزراعي في منطقتك.', array['direct_sowing']::text[], null, null, null, null, null, null, null, '{}'::text[], '{}'::text[]) on conflict (slug) do update set other_names = (public.crops.other_names || array(select x from unnest(excluded.other_names) as u(x) where not (x = any(public.crops.other_names))))[1:12], propagation = case when cardinality(public.crops.propagation) = 0 then excluded.propagation else public.crops.propagation end, data_status = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.data_status else public.crops.data_status end, summary = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.summary else public.crops.summary end, source_note = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.source_note else public.crops.source_note end, primary_method = coalesce(public.crops.primary_method, excluded.primary_method), flowering_note = coalesce(public.crops.flowering_note, excluded.flowering_note), harvest_note = coalesce(public.crops.harvest_note, excluded.harvest_note), first_yield_note = coalesce(public.crops.first_yield_note, excluded.first_yield_note), estimate_dataset = case when public.crops.updated_by is null then excluded.estimate_dataset else public.crops.estimate_dataset end, estimate_harvest_meaning = case when public.crops.updated_by is null then excluded.estimate_harvest_meaning else public.crops.estimate_harvest_meaning end, estimate_note = case when public.crops.updated_by is null then excluded.estimate_note else public.crops.estimate_note end, estimate_links = case when public.crops.updated_by is null then excluded.estimate_links else public.crops.estimate_links end, estimate_review_notes = case when public.crops.updated_by is null then excluded.estimate_review_notes else public.crops.estimate_review_notes end;
insert into public.crop_planting_windows (crop_id, zone, country_code, start_month, end_month, method, note, source_id, source_detail, confidence, optional, sort_order) select (select id from public.crops where slug = 'cucumber'), v.zone, v.country_code, v.start_month, v.end_month, v.method, v.note, v.source_id, v.source_detail, v.confidence, v.optional, v.sort_order from (values ('coastal', null, 3, 5, 'direct_sowing', null, null, null, 'documented', false, 0), ('coastal', null, 8, 9, 'direct_sowing', 'العروة الخريفية', null, null, 'documented', false, 1), ('highland', null, 4, 6, 'direct_sowing', 'بعد دفء التربة', null, null, 'documented', false, 2), ('inland_plain', null, 3, 5, 'direct_sowing', null, null, null, 'documented', false, 3), ('jordan_valley', null, 9, 11, 'direct_sowing', null, null, null, 'documented', false, 4), ('arid', null, 2, 3, 'direct_sowing', null, null, null, 'documented', false, 5), ('arid', null, 9, 10, 'direct_sowing', null, null, null, 'documented', false, 6)) as v(zone, country_code, start_month, end_month, method, note, source_id, source_detail, confidence, optional, sort_order) where not exists (select 1 from public.crop_planting_windows x where x.crop_id = (select id from public.crops where slug = 'cucumber') and x.confidence = 'documented') and (select updated_by from public.crops where slug = 'cucumber') is null;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'cucumber'), 'soil', 'soil_prep', 'تجهيز التربة للخيار', 'أضف سمادًا عضويًا متحللًا، وجهّز شبكة أو دعامة للتسلق إن رغبت.', -7, null, null, '{}'::int[], 0) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'cucumber'), 'sow', 'planting', 'بذر الخيار', 'ازرع 2–3 بذور في كل جورة على عمق 2 سم تقريبًا، ثم اروِ بلطف.', 0, null, null, '{}'::int[], 1) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'cucumber'), 'thin', 'care', 'خف البادرات', 'أبقِ أقوى نبتة في كل جورة وأزل الباقي بقصه دون شده لحماية الجذور.', 12, null, null, '{}'::int[], 2) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'cucumber'), 'water', 'irrigation', 'متابعة ري الخيار', 'افحص رطوبة التربة بإصبعك على عمق 3–5 سم واروِ عند جفافها فقط. تجاوز المهمة إذا هطلت أمطار كافية أو كانت التربة رطبة؛ فالحاجة الفعلية تتأثر بنوع التربة والطقس وعمر النبات.', 1, 2, 75, '{}'::int[], 3) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'cucumber'), 'trellis', 'care', 'توجيه النباتات على الشبكة', 'وجّه المحاليق نحو الدعامة لتحسين التهوية وتقليل الأمراض.', 20, null, null, '{}'::int[], 4) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'cucumber'), 'fert', 'fertilizing', 'تسميد عند بداية التزهير', 'تسميد معتدل متوازن مع الري.', 25, null, null, '{}'::int[], 5) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'cucumber'), 'pests', 'pest_check', 'فحص الخيار من الآفات', 'ابحث عن المن والعنكبوت الأحمر تحت الأوراق، وعن بقع البياض الدقيقي والزغبي.', 10, 7, 75, '{}'::int[], 6) on conflict (crop_id, key) do nothing;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'cucumber'), 'harvest', 'harvest', 'بداية قطف الخيار المتوقع', 'اقطف الثمار وهي صغيرة إلى متوسطة الحجم؛ القطف المتكرر يشجع على إنتاج المزيد.', 50, null, null, '{}'::int[], 7) on conflict (crop_id, key) do nothing;
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'cucumber'), 'overview', 'نظرة عامة', 'الخيار نبات موسمي سريع النمو من العائلة القرعية، يحب الحرارة المعتدلة والشمس، ولا يتحمل البرد. تتوفر أصناف مناسبة للزراعة المكشوفة وأخرى للبيوت المحمية.', 0 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'cucumber') and x.section = 'overview');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'cucumber'), 'planting', 'الزراعة', 'يُزرع بالبذر المباشر غالبًا بعد دفء التربة، أو بالأشتال. تسلّق النبات على شبكة يوفّر المساحة على الأسطح والشرفات ويجعل الثمار أنظف.', 1 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'cucumber') and x.section = 'planting');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'cucumber'), 'care', 'العناية', 'خفّف البادرات، وغطِّ التربة لحفظ الرطوبة، ووجّه النباتات على الدعامة. أزل الأوراق المصابة مبكرًا.', 2 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'cucumber') and x.section = 'care');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'cucumber'), 'irrigation', 'الري', 'الخيار من أكثر الخضار حساسية للعطش. حافظ على رطوبة منتظمة دون غمر، ويفضل الري صباحًا عند قاعدة النبات.', 3 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'cucumber') and x.section = 'irrigation');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'cucumber'), 'fertilization', 'التسميد', 'سماد عضوي عند التجهيز، ثم تسميد معتدل عند التزهير وخلال الإثمار.', 4 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'cucumber') and x.section = 'fertilization');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'cucumber'), 'harvest', 'الحصاد', 'يبدأ القطف تقريبًا بعد 50–70 يومًا من البذر. اقطف بانتظام كل يوم أو يومين في ذروة الإنتاج.', 5 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'cucumber') and x.section = 'harvest');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'cucumber'), 'problems', 'المشكلات الشائعة', 'البياض الدقيقي والبياض الزغبي، والمن، والعنكبوت الأحمر، ومرارة الثمار وتشوهها بسبب العطش أو ضعف التلقيح.', 6 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'cucumber') and x.section = 'problems');
insert into public.crops (slug, name, other_names, scientific_name, category, life_cycle, difficulty, sun, water, frost_sensitive, space_types, growth_days_min, growth_days_max, growth_note, summary, watering_summary, image_alt, data_status, source_note, propagation, primary_method, flowering_note, harvest_note, first_yield_note, estimate_dataset, estimate_harvest_meaning, estimate_note, estimate_links, estimate_review_notes) values ('potato', 'البطاطا', array['البطاطس','البطاطا البلدية']::text[], 'Solanum tuberosum', 'root_tuber', 'annual', 'medium', 'full_sun', 'moderate', true, array['home_garden','rooftop','containers','small_plot','farm']::text[], 90, 120, 'تقريبًا من زراعة الدرنات حتى الحصاد، ويختلف حسب الصنف والعروة.', 'تُزرع من درنات البذور، ولها عادةً عروتان: ربيعية وخريفية. تحتاج إلى تربة خفيفة جيدة الصرف.', 'رطوبة منتظمة خاصة عند تكوّن الدرنات، مع تجنب الغمر.', 'درنات بطاطا طازجة مع التربة', 'preliminary', 'معلومات عامة أولية مجمّعة من الممارسات الزراعية الشائعة في بلاد الشام، ولم تُراجع بعد من مهندس زراعي. تختلف النتائج حسب الصنف والتربة والمناخ المحلي، لذا استشر الإرشاد الزراعي في منطقتك.', array['tubers']::text[], null, null, null, null, null, null, null, '{}'::text[], '{}'::text[]) on conflict (slug) do update set other_names = (public.crops.other_names || array(select x from unnest(excluded.other_names) as u(x) where not (x = any(public.crops.other_names))))[1:12], propagation = case when cardinality(public.crops.propagation) = 0 then excluded.propagation else public.crops.propagation end, data_status = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.data_status else public.crops.data_status end, summary = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.summary else public.crops.summary end, source_note = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.source_note else public.crops.source_note end, primary_method = coalesce(public.crops.primary_method, excluded.primary_method), flowering_note = coalesce(public.crops.flowering_note, excluded.flowering_note), harvest_note = coalesce(public.crops.harvest_note, excluded.harvest_note), first_yield_note = coalesce(public.crops.first_yield_note, excluded.first_yield_note), estimate_dataset = case when public.crops.updated_by is null then excluded.estimate_dataset else public.crops.estimate_dataset end, estimate_harvest_meaning = case when public.crops.updated_by is null then excluded.estimate_harvest_meaning else public.crops.estimate_harvest_meaning end, estimate_note = case when public.crops.updated_by is null then excluded.estimate_note else public.crops.estimate_note end, estimate_links = case when public.crops.updated_by is null then excluded.estimate_links else public.crops.estimate_links end, estimate_review_notes = case when public.crops.updated_by is null then excluded.estimate_review_notes else public.crops.estimate_review_notes end;
insert into public.crop_planting_windows (crop_id, zone, country_code, start_month, end_month, method, note, source_id, source_detail, confidence, optional, sort_order) select (select id from public.crops where slug = 'potato'), v.zone, v.country_code, v.start_month, v.end_month, v.method, v.note, v.source_id, v.source_detail, v.confidence, v.optional, v.sort_order from (values ('coastal', null, 1, 2, 'tubers', 'العروة الربيعية', null, null, 'documented', false, 0), ('coastal', null, 9, 10, 'tubers', 'العروة الخريفية', null, null, 'documented', false, 1), ('highland', null, 3, 4, 'tubers', 'بعد انحسار الصقيع', null, null, 'documented', false, 2), ('highland', null, 8, 8, 'tubers', 'عروة خريفية في المناطق الأدفأ', null, null, 'documented', false, 3), ('inland_plain', null, 2, 3, 'tubers', null, null, null, 'documented', false, 4), ('inland_plain', null, 8, 9, 'tubers', null, null, null, 'documented', false, 5), ('jordan_valley', null, 11, 1, 'tubers', 'الموسم الشتوي', null, null, 'documented', false, 6), ('arid', null, 11, 1, 'tubers', null, null, null, 'documented', false, 7)) as v(zone, country_code, start_month, end_month, method, note, source_id, source_detail, confidence, optional, sort_order) where not exists (select 1 from public.crop_planting_windows x where x.crop_id = (select id from public.crops where slug = 'potato') and x.confidence = 'documented') and (select updated_by from public.crops where slug = 'potato') is null;
insert into public.crop_task_templates (crop_id, key, type, title, description, offset_days, repeat_every_days, until_offset_days, active_months, sort_order) values ((select id from public.crops where slug = 'potato'), 'soil', 'soil_prep', 'تجهيز التربة للبطاطا', 'اقلب التربة جيدًا وأزل الحجارة، وأضف سمادًا عضويًا متحللًا. يمكن استخدام أكياس زراعة كبيرة على الأسطح.', -10, null, null, '{}'::int[], 0) on conflict (crop_id, key) do nothing;
