insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'potato'), 'overview', 'نظرة عامة', 'البطاطا محصول درني يفضّل الأجواء المعتدلة. الحرارة الشديدة تضعف تكوّن الدرنات، والصقيع يتلف المجموع الخضري.', 0 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'potato') and x.section = 'overview');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'potato'), 'planting', 'الزراعة', 'تُزرع من درنات تقاوي سليمة. في الساحل تُزرع غالبًا في الشتاء والخريف، وفي المرتفعات في الربيع، وفي الأغوار في الشتاء.', 1 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'potato') and x.section = 'planting');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'potato'), 'care', 'العناية', 'التحضين (تكويم التراب) أهم عملية؛ فهو يحمي الدرنات من الضوء والحشرات ويزيد المساحة المتاحة لتكوّنها.', 2 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'potato') and x.section = 'care');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'potato'), 'irrigation', 'الري', 'حافظ على رطوبة متوسطة منتظمة، خاصة بعد الإزهار. الغمر يسبب تعفن الدرنات، والعطش يسبب تشوهها.', 3 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'potato') and x.section = 'irrigation');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'potato'), 'fertilization', 'التسميد', 'سماد عضوي جيد التحلل عند التجهيز، وتسميد معتدل قبل تكوّن الدرنات.', 4 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'potato') and x.section = 'fertilization');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'potato'), 'harvest', 'الحصاد', 'بعد 90–120 يومًا تقريبًا عند ذبول الأوراق. احصد في يوم جاف وخزّن الدرنات في مكان مظلم ومهوّى.', 5 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'potato') and x.section = 'harvest');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'potato'), 'problems', 'المشكلات الشائعة', 'اللفحة المتأخرة في الطقس الرطب، وفراشة درنات البطاطا، واخضرار الدرنات عند تعرضها للضوء.', 6 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'potato') and x.section = 'problems');
insert into public.crops (slug, name, other_names, scientific_name, category, life_cycle, difficulty, sun, water, frost_sensitive, space_types, growth_days_min, growth_days_max, growth_note, summary, watering_summary, image_alt, data_status, source_note, propagation, primary_method, flowering_note, harvest_note, first_yield_note, estimate_dataset, estimate_harvest_meaning, estimate_note, estimate_links, estimate_review_notes) values ('onion', 'البصل', array['البصل الأخضر','البصل الأحمر','البصل الأبيض']::text[], 'Allium cepa', 'bulb', 'annual', 'easy', 'full_sun', 'moderate', false, array['home_garden','rooftop','balcony','containers','small_plot','farm']::text[], 100, 150, 'تقريبًا من الشتل حتى نضج الأبصال الجافة. البصل الأخضر يُقطف أبكر بكثير.', 'محصول شتوي سهل، يُزرع بالأشتال أو بالبصيلات الصغيرة، ويمكن قطفه أخضر أو تركه حتى تجف أبصاله.', 'ري معتدل منتظم، ويُخفف قرب النضج.', 'أبصال بصل طازجة', 'preliminary', 'معلومات عامة أولية مجمّعة من الممارسات الزراعية الشائعة في بلاد الشام، ولم تُراجع بعد من مهندس زراعي. تختلف النتائج حسب الصنف والتربة والمناخ المحلي، لذا استشر الإرشاد الزراعي في منطقتك.', array['transplanting']::text[], null, null, null, null, null, null, null, '{}'::text[], '{}'::text[]) on conflict (slug) do update set other_names = (public.crops.other_names || array(select x from unnest(excluded.other_names) as u(x) where not (x = any(public.crops.other_names))))[1:12], propagation = case when cardinality(public.crops.propagation) = 0 then excluded.propagation else public.crops.propagation end, data_status = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.data_status else public.crops.data_status end, summary = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.summary else public.crops.summary end, source_note = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.source_note else public.crops.source_note end, primary_method = coalesce(public.crops.primary_method, excluded.primary_method), flowering_note = coalesce(public.crops.flowering_note, excluded.flowering_note), harvest_note = coalesce(public.crops.harvest_note, excluded.harvest_note), first_yield_note = coalesce(public.crops.first_yield_note, excluded.first_yield_note), estimate_dataset = case when public.crops.updated_by is null then excluded.estimate_dataset else public.crops.estimate_dataset end, estimate_harvest_meaning = case when public.crops.updated_by is null then excluded.estimate_harvest_meaning else public.crops.estimate_harvest_meaning end, estimate_note = case when public.crops.updated_by is null then excluded.estimate_note else public.crops.estimate_note end, estimate_links = case when public.crops.updated_by is null then excluded.estimate_links else public.crops.estimate_links end, estimate_review_notes = case when public.crops.updated_by is null then excluded.estimate_review_notes else public.crops.estimate_review_notes end;
