insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'onion'), 'care', 'العناية', 'التعشيب المنتظم ضروري لأن البصل لا ينافس الأعشاب جيدًا. لا تكوّم التراب فوق الأبصال.', 2 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'onion') and x.section = 'care');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'onion'), 'irrigation', 'الري', 'ري معتدل منتظم خلال النمو، ثم تخفيفه عند بدء النضج لتحسين التخزين.', 3 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'onion') and x.section = 'irrigation');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'onion'), 'fertilization', 'التسميد', 'سماد عضوي متحلل عند التجهيز، وتسميد معتدل في بداية النمو.', 4 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'onion') and x.section = 'fertilization');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'onion'), 'harvest', 'الحصاد', 'عند انحناء الأوراق وجفافها، تُقلع الأبصال وتُترك لتجف في مكان مظلل وجيد التهوية.', 5 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'onion') and x.section = 'harvest');
