rops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.source_note else public.crops.source_note end, primary_method = coalesce(public.crops.primary_method, excluded.primary_method), flowering_note = coalesce(public.crops.flowering_note, excluded.flowering_note), harvest_note = coalesce(public.crops.harvest_note, excluded.harvest_note), first_yield_note = coalesce(public.crops.first_yield_note, excluded.first_yield_note), estimate_dataset = case when public.crops.updated_by is null then excluded.estimate_dataset else public.crops.estimate_dataset end, estimate_harvest_meaning = case when public.crops.updated_by is null then excluded.estimate_harvest_meaning else public.crops.estimate_harvest_meaning end, estimate_note = case when public.crops.updated_by is null then excluded.estimate_note else public.crops.estimate_note end, estimate_links = case when public.crops.updated_by is null then excluded.estimate_links else public.crops.estimate_links end, estimate_review_notes = case when public.crops.updated_by is null then excluded.estimate_review_notes else public.crops.estimate_review_notes end;
