insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'garlic'), 'planting', 'الزراعة', 'يُزرع في الخريف (تشرين الأول – كانون الأول تقريبًا) بفصوص كبيرة من رؤوس سليمة.', 1 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'garlic') and x.section = 'planting');
