insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'lettuce'), 'care', 'العناية', 'يستفيد من ظل جزئي في الأيام الدافئة. الزراعة المتتابعة كل أسبوعين تضمن إنتاجًا مستمرًا.', 2 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'lettuce') and x.section = 'care');
