insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'zaatar'), 'care', 'العناية', 'يحتاج إلى شمس كاملة وتربة جيدة الصرف. التقليم الخفيف بعد الإزهار يحافظ على شكل النبات.', 2 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'zaatar') and x.section = 'care');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'zaatar'), 'irrigation', 'الري', 'اروِه بانتظام حتى يثبت، ثم قلل الري كثيرًا. التربة المشبعة بالماء تسبب تعفن الجذور.', 3 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'zaatar') and x.section = 'irrigation');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'zaatar'), 'fertilization', 'التسميد', 'لا يحتاج إلى تسميد كثيف؛ كمية قليلة من الكمبوست سنويًا تكفي.', 4 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'zaatar') and x.section = 'fertilization');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'zaatar'), 'harvest', 'الحصاد', 'تُقطف الأفرع الطرية والأوراق، ويُفضّل عدم قص النبات بالكامل. يجفف الزعتر في الظل.', 5 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'zaatar') and x.section = 'harvest');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'zaatar'), 'problems', 'المشكلات الشائعة', 'تعفن الجذور من الري الزائد، والمن، وضعف النمو في الظل.', 6 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'zaatar') and x.section = 'problems');
