insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'olive'), 'planting', 'الزراعة', 'تُزرع الغراس غالبًا في الشتاء وبداية الربيع مستفيدة من الأمطار. اختر مكانًا مشمسًا جيد الصرف.', 1 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'olive') and x.section = 'planting');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'olive'), 'care', 'العناية', 'التقليم التكويني في السنوات الأولى يحدد شكل الشجرة. احمِ الغراس الصغيرة من الرعي والأعشاب.', 2 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'olive') and x.section = 'care');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'olive'), 'irrigation', 'الري', 'الري في الصيف الأول والثاني مهم لنجاح الغراس، ثم يعتمد الزيتون البعلي على المطر غالبًا.', 3 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'olive') and x.section = 'irrigation');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'olive'), 'fertilization', 'التسميد', 'سماد عضوي متحلل في الشتاء، والتسميد الكيماوي يحدد حسب تحليل التربة.', 4 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'olive') and x.section = 'fertilization');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'olive'), 'harvest', 'الحصاد', 'موسم القطاف في فلسطين عادة في تشرين الأول وتشرين الثاني، لكن الغراس الجديدة تحتاج إلى سنوات قبل الإنتاج.', 5 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'olive') and x.section = 'harvest');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'olive'), 'problems', 'المشكلات الشائعة', 'ذبابة ثمار الزيتون، وعين الطاووس (مرض فطري على الأوراق)، والمعاومة (تذبذب الحمل بين عام وآخر).', 6 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'olive') and x.section = 'problems');
insert into public.crops (slug, name, other_names, scientific_name, category, life_cycle, difficulty, sun, water, frost_sensitive, space_types, growth_days_min, growth_days_max, growth_note, summary, watering_summary, image_alt, data_status, source_note, propagation, primary_method, flowering_note, harvest_note, first_yield_note, estimate_dataset, estimate_harvest_meaning, estimate_note, estimate_links, estimate_review_notes) values ('grape', 'العنب', array['الدوالي','الكرمة','ورق العنب','العريشة']::text[], 'Vitis vinifera', 'tree', 'perennial', 'medium', 'full_sun', 'low', false, array['home_garden','rooftop','small_plot','farm']::text[], null, null, 'كرمة معمّرة؛ يبدأ الإنتاج عادةً بعد سنتين إلى ثلاث من الزراعة حسب الصنف والعناية.', 'الدالية جزء من البيت الشامي، ويمكن تربيتها على عريشة فوق السطح أو الساحة. تشتهر الخليل بكرومها.', 'الكرمة الصغيرة تحتاج إلى ري صيفي، والكرمة الكبيرة تتحمل الجفاف نسبيًا.', 'عنقود عنب ناضج', 'preliminary', 'معلومات عامة أولية مجمّعة من الممارسات الزراعية الشائعة في بلاد الشام، ولم تُراجع بعد من مهندس زراعي. تختلف النتائج حسب الصنف والتربة والمناخ المحلي، لذا استشر الإرشاد الزراعي في منطقتك.', array['saplings']::text[], null, null, null, 'كرمة معمّرة؛ يبدأ الإنتاج عادةً بعد سنتين إلى ثلاث من الزراعة حسب الصنف والعناية.', null, null, null, '{}'::text[], '{}'::text[]) on conflict (slug) do update set other_names = (public.crops.other_names || array(select x from unnest(excluded.other_names) as u(x) where not (x = any(public.crops.other_names))))[1:12], propagation = case when cardinality(public.crops.propagation) = 0 then excluded.propagation else public.crops.propagation end, data_status = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.data_status else public.crops.data_status end, summary = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.summary else public.crops.summary end, source_note = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.source_note else public.crops.source_note end, primary_method = coalesce(public.crops.primary_method, excluded.primary_method), flowering_note = coalesce(public.crops.flowering_note, excluded.flowering_note), harvest_note = coalesce(public.crops.harvest_note, excluded.harvest_note), first_yield_note = coalesce(public.crops.first_yield_note, excluded.first_yield_note), estimate_dataset = case when public.crops.updated_by is null then excluded.estimate_dataset else public.crops.estimate_dataset end, estimate_harvest_meaning = case when public.crops.updated_by is null then excluded.estimate_harvest_meaning else public.crops.estimate_harvest_meaning end, estimate_note = case when public.crops.updated_by is null then excluded.estimate_note else public.crops.estimate_note end, estimate_links = case when public.crops.updated_by is null then excluded.estimate_links else public.crops.estimate_links end, estimate_review_notes = case when public.crops.updated_by is null then excluded.estimate_review_notes else public.crops.estimate_review_notes end;
insert into public.crop_planting_windows (crop_id, zone, country_code, start_month, end_month, method, note, source_id, source_detail, confidence, optional, sort_order) select (select id from public.crops where slug = 'grape'), v.zone, v.country_code, v.start_month, v.end_month, v.method, v.note, v.source_id, v.source_detail, v.confidence, v.optional, v.sort_order from (values ('coastal', null, 12, 2, 'saplings', 'فترة السكون', null, null, 'documented', false, 0), ('highland', null, 12, 3, 'saplings', 'فترة السكون', null, null, 'documented', false, 1), ('inland_plain', null, 12, 2, 'saplings', null, null, null, 'documented', false, 2), ('jordan_valley', null, 12, 1, 'saplings', null, null, null, 'documented', false, 3), ('arid', null, 12, 1, 'saplings', null, null, null, 'documented', false, 4)) as v(zone, country_code, start_month, end_month, method, note, source_id, source_detail, confidence, optional, sort_order) where not exists (select 1 from public.crop_planting_windows x where x.crop_id = (select id from public.crops where slug = 'grape') and x.confidence = 'documented') and (select updated_by from public.crops where slug = 'grape') is null;
