insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'grape'), 'overview', 'نظرة عامة', 'العنب كرمة معمّرة متساقطة الأوراق، تحب الشمس والصيف الجاف، وتحتاج إلى برودة الشتاء في كثير من الأصناف.', 0 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'grape') and x.section = 'overview');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'grape'), 'planting', 'الزراعة', 'تُزرع الغراس في فترة السكون الشتوي، مع دعامة أو عريشة قوية.', 1 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'grape') and x.section = 'planting');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'grape'), 'care', 'العناية', 'التقليم الشتوي هو أهم عملية لتحديد الإنتاج وشكل الكرمة. وجّه الأفرع على العريشة خلال الربيع.', 2 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'grape') and x.section = 'care');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'grape'), 'irrigation', 'الري', 'الكرمة الحديثة تحتاج إلى ري صيفي منتظم، أما الكبيرة فتتحمل الجفاف لكن الري المعتدل يحسن الإنتاج.', 3 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'grape') and x.section = 'irrigation');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'grape'), 'fertilization', 'التسميد', 'سماد عضوي في الشتاء، وتسميد معتدل في الربيع.', 4 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'grape') and x.section = 'fertilization');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'grape'), 'harvest', 'الحصاد', 'يقطف العنب عند اكتمال اللون والحلاوة، ويختلف الموعد كثيرًا بين الأصناف والمناطق.', 5 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'grape') and x.section = 'harvest');
insert into public.crop_guides (crop_id, section, title, body, sort_order) select (select id from public.crops where slug = 'grape'), 'problems', 'المشكلات الشائعة', 'البياض الدقيقي، والبياض الزغبي، وحشرات البق الدقيقي، وتعفن العناقيد في الرطوبة.', 6 where not exists (select 1 from public.crop_guides x where x.crop_id = (select id from public.crops where slug = 'grape') and x.section = 'problems');
insert into public.crops (slug, name, other_names, scientific_name, category, life_cycle, difficulty, sun, water, frost_sensitive, space_types, growth_days_min, growth_days_max, growth_note, summary, watering_summary, image_alt, data_status, source_note, propagation, primary_method, flowering_note, harvest_note, first_yield_note, estimate_dataset, estimate_harvest_meaning, estimate_note, estimate_links, estimate_review_notes) values ('eggplant', 'الباذنجان', array['البتنجان','الباذنجان البلدي']::text[], 'Solanum melongena', 'fruiting_vegetable', 'annual', null, null, null, false, '{}'::text[], null, null, null, 'شتلات جاهزة؛ يتأخر الحصاد أو يتقدم حسب الصنف وحرارة الليل؛ الأشهر نطاقات استرشادية وليست قرارًا زراعيًا نهائيًا.', null, 'رسم توضيحي: الباذنجان', 'estimated', 'هذه مواعيد تقديرية قد تختلف بحسب الصنف والمنطقة والطقس. هي تقدير عام غير موثّق لهذا الصنف ولم يراجعه مختص، لمناطق فلسطين المناخية فقط، ولا تُعرض لموقع في دولة أخرى. الروابط المرفقة مراجع سياقية عامة ولا تثبت كل موعد. تأكد من الإرشاد الزراعي في منطقتك.', array['transplanting','nursery_sowing']::text[], 'transplanting', null, null, null, 'smartplant-88-ps', 'ثمار على نبات قائم', 'شتلات جاهزة؛ يتأخر الحصاد أو يتقدم حسب الصنف وحرارة الليل؛ الأشهر نطاقات استرشادية وليست قرارًا زراعيًا نهائيًا.', array['https://info.wafa.ps/Pages/Details/32243']::text[], '{}'::text[]) on conflict (slug) do update set other_names = (public.crops.other_names || array(select x from unnest(excluded.other_names) as u(x) where not (x = any(public.crops.other_names))))[1:12], propagation = case when cardinality(public.crops.propagation) = 0 then excluded.propagation else public.crops.propagation end, data_status = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.data_status else public.crops.data_status end, summary = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.summary else public.crops.summary end, source_note = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.source_note else public.crops.source_note end, primary_method = coalesce(public.crops.primary_method, excluded.primary_method), flowering_note = coalesce(public.crops.flowering_note, excluded.flowering_note), harvest_note = coalesce(public.crops.harvest_note, excluded.harvest_note), first_yield_note = coalesce(public.crops.first_yield_note, excluded.first_yield_note), estimate_dataset = case when public.crops.updated_by is null then excluded.estimate_dataset else public.crops.estimate_dataset end, estimate_harvest_meaning = case when public.crops.updated_by is null then excluded.estimate_harvest_meaning else public.crops.estimate_harvest_meaning end, estimate_note = case when public.crops.updated_by is null then excluded.estimate_note else public.crops.estimate_note end, estimate_links = case when public.crops.updated_by is null then excluded.estimate_links else public.crops.estimate_links end, estimate_review_notes = case when public.crops.updated_by is null then excluded.estimate_review_notes else public.crops.estimate_review_notes end;
