rops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.summary else public.crops.summary end, source_note = case when public.crops.data_status = 'incomplete' and public.crops.updated_by is null and excluded.data_status <> 'incomplete' then excluded.source_note else public.crops.source_note end, primary_method = coalesce(public.crops.primary_method, excluded.primary_method), flowering_note = coalesce(public.crops.flowering_note, excluded.flowering_note), harvest_note = coalesce(public.crops.harvest_note, excluded.harvest_note), first_yield_note = coalesce(public.crops.first_yield_note, excluded.first_yield_note), estimate_dataset = case when public.crops.updated_by is null then excluded.estimate_dataset else public.crops.estimate_dataset end, estimate_harvest_meaning = case when public.crops.updated_by is null then excluded.estimate_harvest_meaning else public.crops.estimate_harvest_meaning end, estimate_note = case when public.crops.updated_by is null then excluded.estimate_note else public.crops.estimate_note end, estimate_links = case when public.crops.updated_by is null then excluded.estimate_links else public.crops.estimate_links end, estimate_review_notes = case when public.crops.updated_by is null then excluded.estimate_review_notes else public.crops.estimate_review_notes end;
insert into public.crop_planting_windows (crop_id, zone, country_code, start_month, end_month, method, note, source_id, source_detail, confidence, optional, sort_order) select (select id from public.crops where slug = 'caper'), v.zone, v.country_code, v.start_month, v.end_month, v.method, v.note, v.source_id, v.source_detail, v.confidence, v.optional, v.sort_order from (values ('highland', 'PS', 3, 4, 'transplanting', null, null, null, 'estimated', false, 0), ('coastal', 'PS', 3, 4, 'transplanting', null, null, null, 'estimated', false, 1), ('inland_plain', 'PS', 3, 4, 'transplanting', null, null, null, 'estimated', false, 2), ('jordan_valley', 'PS', 4, 5, 'transplanting', null, null, null, 'estimated', false, 3), ('arid', 'PS', 3, 4, 'transplanting', null, null, null, 'estimated', false, 4)) as v(zone, country_code, start_month, end_month, method, note, source_id, source_detail, confidence, optional, sort_order) where (select updated_by from public.crops where slug = 'caper') is null;
insert into public.crop_phase_windows (crop_id, kind, zone, country_code, start_month, end_month, confidence, optional, sort_order) select (select id from public.crops where slug = 'caper'), v.kind, v.zone, v.country_code, v.start_month, v.end_month, 'estimated', v.optional, v.sort_order from (values ('flowering', 'highland', 'PS', 4, 9, false, 0), ('harvest', 'highland', 'PS', 5, 9, false, 1), ('flowering', 'coastal', 'PS', 4, 9, false, 2), ('harvest', 'coastal', 'PS', 5, 9, false, 3), ('flowering', 'inland_plain', 'PS', 4, 9, false, 4), ('harvest', 'inland_plain', 'PS', 5, 9, false, 5), ('flowering', 'jordan_valley', 'PS', 3, 8, false, 6), ('harvest', 'jordan_valley', 'PS', 4, 8, false, 7), ('flowering', 'arid', 'PS', 4, 9, false, 8), ('harvest', 'arid', 'PS', 5, 9, false, 9)) as v(kind, zone, country_code, start_month, end_month, optional, sort_order) where (select updated_by from public.crops where slug = 'caper') is null;
insert into public.crop_zone_estimates (crop_id, zone, country_code, suitability, irrigation, days_to_first_harvest, years_to_first_yield, not_applicable) select (select id from public.crops where slug = 'caper'), v.zone, v.country_code, v.suitability, v.irrigation, v.days, v.years, v.na from (values ('highland', 'PS', 'local_guidance', 'supplemental', null::int, 2::int, array['days']::text[]), ('coastal', 'PS', 'local_guidance', 'supplemental', null::int, 2::int, array['days']::text[]), ('inland_plain', 'PS', 'local_guidance', 'supplemental', null::int, 2::int, array['days']::text[]), ('jordan_valley', 'PS', 'local_guidance', 'supplemental', null::int, 2::int, array['days']::text[]), ('arid', 'PS', 'needs_irrigation', 'irrigated_only', null::int, 2::int, array['days']::text[])) as v(zone, country_code, suitability, irrigation, days, years, na) where (select updated_by from public.crops where slug = 'caper') is null on conflict (crop_id, zone, country_code) do nothing;
insert into public.faqs (question, answer, sort_order) select 'هل استخدام رزنامة الزراعة الذكية مجاني؟', 'نعم، جميع المزايا الأساسية متاحة مجانًا: دليل المحاصيل، ومولّد الخطط، والرزنامة، وإدارة المهام. قد نضيف مستقبلًا مزايا متقدمة اختيارية دون المساس بالنسخة الأساسية.', 0 where not exists (select 1 from public.faqs where question = 'هل استخدام رزنامة الزراعة الذكية مجاني؟');
insert into public.faqs (question, answer, sort_order) select 'هل مواعيد الزراعة في المنصة دقيقة لمنطقتي؟', 'المواعيد الحالية تقديرات أولية عامة مبنية على المناطق المناخية في بلاد الشام (ساحلي، جبلي، سهلي، غور، صحراوي). نوضح ذلك في كل صفحة، وننصح دائمًا بمراجعة الإرشاد الزراعي المحلي لأن الصنف والتربة والارتفاع تؤثر كثيرًا.', 1 where not exists (select 1 from public.faqs where question = 'هل مواعيد الزراعة في المنصة دقيقة لمنطقتي؟');
insert into public.faqs (question, answer, sort_order) select 'هل أحتاج إلى حساب لإنشاء خطة زراعية؟', 'لا. يمكنك إنشاء خطة وتجربتها مباشرة، وتُحفظ في متصفحك على هذا الجهاز فقط. عند إنشاء حساب تُحفظ خططك ومهامك في قاعدة البيانات وتجدها من أي جهاز، ويمكنك نقل بياناتك المحلية إلى حسابك.', 2 where not exists (select 1 from public.faqs where question = 'هل أحتاج إلى حساب لإنشاء خطة زراعية؟');
insert into public.faqs (question, answer, sort_order) select 'من أين تأتي بيانات الطقس؟', 'نعرض توقعات الطقس من خدمة Open-Meteo المفتوحة لعدة أيام قادمة فقط، مع ذكر المصدر ووقت التحديث. لا نعرض توقعات لأشهر قادمة لأنها غير متوفرة بدقة كافية.', 3 where not exists (select 1 from public.faqs where question = 'من أين تأتي بيانات الطقس؟');
insert into public.faqs (question, answer, sort_order) select 'هل تخبرني المنصة متى أروي نباتاتي بالضبط؟', 'نقترح مواعيد لمتابعة الري ونذكّرك بها، لكن الحاجة الفعلية للري تعتمد على رطوبة التربة ونوعها وعمر النبات والطقس. لذلك ننصح بفحص التربة قبل الري، ولا نعتمد على درجة الحرارة وحدها.', 4 where not exists (select 1 from public.faqs where question = 'هل تخبرني المنصة متى أروي نباتاتي بالضبط؟');
insert into public.faqs (question, answer, sort_order) select 'هل يمكنني تعديل المهام المقترحة؟', 'نعم. يمكنك تعديل تاريخ أي مهمة أو وصفها، ووضعها كمكتملة أو تأجيلها أو حذفها، وإضافة مهامك الخاصة وربطها بمحاصيلك.', 5 where not exists (select 1 from public.faqs where question = 'هل يمكنني تعديل المهام المقترحة؟');
insert into public.faqs (question, answer, sort_order) select 'هل تصلني تذكيرات على البريد أو الهاتف؟', 'حاليًا تظهر التذكيرات داخل المنصة للمهام القريبة والمتأخرة. البنية جاهزة لإضافة البريد الإلكتروني والإشعارات الفورية لاحقًا، ولن نفعّلها قبل ربط خدمة حقيقية واختبارها.', 6 where not exists (select 1 from public.faqs where question = 'هل تصلني تذكيرات على البريد أو الهاتف؟');
insert into public.site_settings (key, value) values ('weather_thresholds', '{"frostTempC":2,"heatTempC":35,"rainProbabilityPct":60,"heavyRainMm":20,"strongWindKmh":40}'::jsonb) on conflict (key) do nothing;
insert into public.site_settings (key, value) values ('contact', '{"email": ""}'::jsonb) on conflict (key) do nothing;
